import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.cNy3aYYk.js";const h=JSON.parse('{"title":"Communication Templates 1.1.0 (shared/private) — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Communication Templates 1.1.0 (shared/private) — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/communication-templates-1-1-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Communication Templates 1.1.0 (shared/private) — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/communication-templates-1-1-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/communication-templates-1-1-0-production-readiness.md","filePath":"deployment/communication-templates-1-1-0-production-readiness.md","lastUpdated":1791586880000}'),d={name:"deployment/communication-templates-1-1-0-production-readiness.md"};function s(r,e,n,l,c,m){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="communication-templates-1-1-0-shared-private-—-production-readiness-audit" tabindex="-1">Communication Templates 1.1.0 (shared/private) — Production Readiness Audit <a class="header-anchor" href="#communication-templates-1-1-0-shared-private-—-production-readiness-audit" aria-label="Permalink to &quot;Communication Templates 1.1.0 (shared/private) — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-09</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> (migrate-only + deploy SPA/Mobile)</td></tr><tr><td><strong>Scope</strong></td><td><code>is_shared</code> visibility parity with Email templates; catalog <strong>communication-templates 1.0.0 → 1.1.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="/deployment/communication-templates">Communication Templates deploy</a> · <a href="/deployment/upgrade">Upgrade</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>WhatsApp (Communication) templates now support <strong>Shared with workspace</strong> / <strong>Private</strong>, matching Email templates: teammates use shared templates; only the creator or workspace owner edits/deletes; pickers never surface others’ private templates.</p><p><strong>Go / No-Go:</strong> <strong>Go</strong>.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze (no new shell; Templates module only)</td><td><strong>Pass</strong></td></tr><tr><td>Schema + backfill existing rows shared</td><td><strong>Pass</strong> — migration defaults + <code>UPDATE … is_shared = true</code></td></tr><tr><td>List scope own + shared; owner sees private on manage</td><td><strong>Pass</strong> — Pest</td></tr><tr><td>Picker <code>for_use=1</code> own + shared + active</td><td><strong>Pass</strong> — Pest + SPA picker</td></tr><tr><td>Update/delete creator or owner</td><td><strong>Pass</strong> — Pest</td></tr><tr><td>Resource <code>can_edit</code> / <code>can_delete</code></td><td><strong>Pass</strong> — Pest + SPA row actions</td></tr><tr><td>Catalog migrate-only + CatalogSeeder companion</td><td><strong>Pass</strong> — <strong>1.1.0</strong></td></tr><tr><td>SPA Shared toggle + visibility column/filter</td><td><strong>Pass</strong></td></tr><tr><td>Mobile Shared/Private create/edit/list/view</td><td><strong>Pass</strong></td></tr><tr><td>Docs + CHANGELOG same delivery</td><td><strong>Pass</strong></td></tr><tr><td>Playwright headed one-session (validation + shared/private CRUD)</td><td><strong>Pass</strong> — <code>npm run test:e2e:communication-templates:headed</code></td></tr></tbody></table><h2 id="findings-and-remediations" tabindex="-1">Findings and remediations <a class="header-anchor" href="#findings-and-remediations" aria-label="Permalink to &quot;Findings and remediations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Resolution</th></tr></thead><tbody><tr><td>CT-01</td><td>High</td><td>Communication templates were always workspace-visible; no private drafts</td><td>Added <code>is_shared</code> + visibility scopes mirroring Email</td></tr><tr><td>CT-02</td><td>Medium</td><td>Staff with <code>update</code> could edit teammates’ templates</td><td>Policy: creator or workspace owner only</td></tr><tr><td>CT-03</td><td>Medium</td><td>WhatsApp picker could list inactive/private templates inconsistently</td><td>SPA list uses <code>for_use=true</code> (active + own/shared)</td></tr><tr><td>CT-04</td><td>Low</td><td>Row Edit/Delete gated only by Spatie permission, not ownership</td><td>UI uses <code>can_edit</code> / <code>can_delete</code> from API</td></tr><tr><td>CT-05</td><td>Low</td><td>Existing rows would become private if defaulted false</td><td>Backfill <code>true</code> to preserve pre-1.1.0 behavior</td></tr></tbody></table><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li>Migration <code>2026_10_09_145841_add_is_shared_to_communication_templates_table</code></li><li>Catalog bump <code>2026_10_09_145845_bump_communication_templates_module_to_1_1_0</code></li><li><code>CommunicationTemplateService</code> visibility + <code>for_use</code> / <code>is_shared</code> filters</li><li><code>CommunicationTemplatePolicy</code> view/use/update/delete ownership rules</li><li>Resource fields <code>is_shared</code>, <code>can_edit</code>, <code>can_delete</code></li><li>Pest: <code>CommunicationTemplateSharingTest</code></li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li>Form <strong>Shared with workspace</strong> switch (default on)</li><li>List Visibility column + filter; creator column; ownership-aware actions</li><li>WhatsApp picker <code>for_use: true</code></li><li>Playwright: one-session validation + shared/private CRUD (<code>test:e2e:communication-templates:headed</code>)</li></ul><h3 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h3><ul><li>Visibility cycle on create/edit; Shared/Private on list/view; <code>can_edit</code> / <code>can_delete</code> gates</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>User / developer / API / deployment guides, changelog, this audit</li></ul><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>herd php vendor/bin/pest --compact tests/Feature/Tenant/CommunicationTemplates/</span></span></code></pre></div><p>Pest: <strong>18 passed</strong> (140 assertions).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm run test:e2e:communication-templates:headed</span></span></code></pre></div><p>Playwright headed (<code>E2E_VIDEO=off</code>, bundled Chromium, <code>--workers=1</code>): <strong>1 passed</strong> — empty-form validation, shared + private create, visibility filter, edit share flag → private, delete both.</p><p><code>vendor/bin/pint --dirty --format agent</code> — pass.</p><h2 id="known-limitations-deferred" tabindex="-1">Known limitations / deferred <a class="header-anchor" href="#known-limitations-deferred" aria-label="Permalink to &quot;Known limitations / deferred&quot;">​</a></h2><ul><li>Meta WhatsApp Cloud templates (<code>whatsapp_cloud_templates</code>) remain a separate sync model; sharing does not apply.</li><li>No multi-user Playwright ownership matrix (creator vs staff) in headed browser; covered by Pest API tests.</li><li>Templates with <code>created_by</code> null are only editable by the workspace owner.</li></ul><h2 id="upgrade-staging-smoke" tabindex="-1">Upgrade &amp; staging smoke <a class="header-anchor" href="#upgrade-staging-smoke" aria-label="Permalink to &quot;Upgrade &amp; staging smoke&quot;">​</a></h2><ol><li><code>php artisan migrate --force</code> — <code>is_shared</code> column + catalog <strong>1.1.0</strong> (do <strong>not</strong> <code>db:seed</code>).</li><li>Deploy Frontend SPA + Mobile as needed.</li><li>Templates → New: Shared on by default; create private; confirm Visibility column.</li><li>Staff account: sees shared only; cannot edit owner’s shared template; picker omits private.</li><li>Lead/Help Desk WhatsApp picker: private templates of other users absent.</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/deployment/communication-templates">Communication Templates — Deployment</a></li><li><a href="/developer-guide/communication-templates">Developer guide</a></li><li><a href="/user-guide/communication-templates">User guide</a></li></ul>',30)])])}const u=t(d,[["render",s]]);export{h as __pageData,u as default};
